// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0) && actor != address(c) && actor != address(this));
        vm.assume(amount > 0);

        uint256 preContractBalance = address(c).balance;
        uint256 preBalance = c.getBalance(actor);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.addToBalance{value: amount}();

        uint256 postContractBalance = address(c).balance;
        uint256 postBalance = c.getBalance(actor);

        assertTrue(preContractBalance + amount == postContractBalance && preBalance + amount == postBalance);
    }
}
